using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Extracts text or caption of the given message and translates it to the given language. If the current user is a Telegram Premium user, then text formatting is preserved
    /// </summary>
    public Task<TdLib.TdApi.Objects.FormattedText> TranslateMessageTextAsync(long chatId = default, long messageId = default, string toLanguageCode = default)
    {

           using var activity =  StartCallActivity("TranslateMessageTextAsync", typeof(TranslateMessageText).FullName ?? "TranslateMessageTextAsync");

           try
           {
             return client.TranslateMessageTextAsync(chatId, messageId, toLanguageCode);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
